"""Self-contained HTML reports. All input strings are escaped; no scripts or assets."""
from html import escape
import difflib


def html_report(report: dict) -> str:
    e = lambda value: escape(str(value), quote=True)
    status = report["status"]
    title = {"passed": "Ready for a closer look.", "review": "A change worth reviewing.", "failed": "Caught before production."}[status]
    steps = "".join(f'<tr><td class="mono">{i:02}</td><td>{e(s["file"])}</td><td><span class="tag {s["status"]}">{e(s["status"].replace("_", " "))}</span></td><td>{s["statements"]}</td><td>{s["changed_rows"]}</td></tr>' for i, s in enumerate(report["steps"], 1))
    diffs = []
    for change in report["changes"]:
        old, new = change["before"], change["after"]
        lines = difflib.unified_diff(((old or {}).get("sql") or "").splitlines(), ((new or {}).get("sql") or "").splitlines(), fromfile="before", tofile="after", lineterm="")
        code = "".join(f'<div class="{"add" if line.startswith("+") else "remove" if line.startswith("-") else "context"}">{e(line) or " "}</div>' for line in lines)
        rows = f'{old.get("rows", "—") if old else "—"} → {new.get("rows", "—") if new else "—"}'
        diffs.append(f'<article><div class="object-heading"><h3>{e(change["object"])}</h3><span class="tag">{e(change["status"])}</span></div><p class="muted">Rows: {e(rows)}</p><pre>{code or "No DDL change; row count changed."}</pre></article>')
    risks = "".join(f'<li>{e(r)}</li>' for r in report["risks"])
    checks = report["checks"]
    check_text = "Not completed" if checks is None else "Passed" if checks["passed"] else "Failed"
    error = f'<div class="error"><strong>Rehearsal stopped</strong><p>{e(report["error"])}</p></div>' if report["error"] else ""
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Patchday · {e(report['database'])}</title><link rel="icon" href="data:,"><meta name="description" content="SQLite migration rehearsal on a disposable snapshot."><style>
:root{{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#202a29;background:#f4f6f3}}*{{box-sizing:border-box}}body{{margin:0}}header{{background:#153e32;color:#fff;padding:28px max(6%,calc((100vw - 1120px)/2));display:flex;justify-content:space-between;align-items:center}}.brand{{font-size:25px;font-weight:650;letter-spacing:-1px}}.brand b{{color:#a4d681;margin-right:8px}}.mono,.eyebrow{{font-family:ui-monospace,SFMono-Regular,monospace}}header .mono{{font-size:11px;letter-spacing:1px;color:#bad1c4}}main{{max-width:1120px;margin:auto;padding:48px 36px}}.eyebrow{{font-size:11px;letter-spacing:1.5px;color:#567767}}h1{{font-size:clamp(30px,4vw,48px);letter-spacing:-1.8px;font-weight:550;margin:14px 0}}.sub{{color:#667970;line-height:1.7;font-size:15px}}.meta{{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #ccd7cd;margin:32px 0;background:#fff;border-radius:5px}}.meta div{{padding:22px;border-right:1px solid #dce3dd}}.meta div:last-child{{border:0}}.meta span{{display:block;font-size:11px;color:#667970;margin-bottom:10px}}.meta strong{{font-size:25px;font-weight:550}}.status{{color:{'#ad4327' if status == 'failed' else '#8e6119' if status == 'review' else '#20704e'}}}.section-title{{display:flex;justify-content:space-between;align-items:center;margin:35px 0 15px}}h2{{font-size:20px;font-weight:550;letter-spacing:-.5px}}.section-title .mono{{font-size:11px;color:#748176}}table{{border-collapse:collapse;width:100%;background:white;font-size:13px;border:1px solid #d6ded6}}th{{text-align:left;font-size:10px;letter-spacing:1px;color:#607569;background:#edf2ec}}td,th{{padding:15px;border-bottom:1px solid #e4e9e2}}td:first-child{{color:#72927c}}.tag{{font:10px ui-monospace,monospace;background:#e7eee5;color:#326449;border-radius:3px;padding:5px 8px;display:inline-block}}.tag.failed,.tag.rolled_back{{color:#a13925;background:#f8e4dd}}.notice,.error{{padding:20px 24px;border-left:3px solid #ae7e2c;background:#fff8e8;margin:24px 0;font-size:14px;line-height:1.7}}.error{{background:#fff0e9;border-color:#b55436}}.notice ul{{padding-left:18px;margin-bottom:0}}.objects{{display:grid;gap:16px}}article{{border:1px solid #d5dfd3;background:#fff;border-radius:5px;overflow:hidden}}.object-heading{{padding:18px 22px 0;display:flex;align-items:center;justify-content:space-between}}h3{{font:14px ui-monospace,monospace;margin:0}}.muted{{font-size:11px;color:#6c7c71;padding:0 22px}}pre{{margin:18px 0 0;background:#f9fbf8;overflow:auto;font:12px/1.8 ui-monospace,monospace;padding:15px 0}}pre div{{padding:0 22px;white-space:pre-wrap;overflow-wrap:anywhere}}.add{{color:#25683c;background:#eaf5e8}}.remove{{color:#a3402a;background:#fff0e9}}.context{{color:#65786a}}.notes{{margin-top:36px;border-top:1px solid #d5dfd3;padding-top:20px;display:grid;grid-template-columns:1fr 1fr;gap:45px}}.notes h3{{font-family:inherit;font-size:15px}}.notes p{{font-size:13px;line-height:1.8;color:#68796d}}footer{{margin-top:36px;padding-top:20px;border-top:1px solid #d5dfd3;display:flex;justify-content:space-between;font:10px ui-monospace,monospace;color:#667970}}@media(max-width:650px){{main{{padding:28px 16px}}.meta{{grid-template-columns:1fr 1fr}}.meta div{{padding:18px}}.meta div:nth-child(2){{border-right:0}}.meta div:nth-child(-n+2){{border-bottom:1px solid #dce3dd}}.notes{{grid-template-columns:1fr;gap:15px}}td,th{{padding:10px 7px;font-size:11px}}header .mono{{display:none}}.table-wrap{{overflow:auto}}}}
</style></head><body><header><span class="brand"><b>▤</b>Patchday</span><span class="mono">SQLITE MIGRATION REHEARSAL</span></header><main>
<p class="eyebrow">REHEARSAL REPORT / {e(report['database'])}</p><h1>{title}</h1><p class="sub">A migration run against a disposable snapshot.<br>The source database was opened read-only. No changes were applied to it.</p>
<div class="meta"><div><span>RESULT</span><strong class="status">{e(status.title())}</strong></div><div><span>MIGRATIONS RUN</span><strong>{len(report['steps']):02}</strong></div><div><span>OBJECTS CHANGED</span><strong>{len(report['changes']):02}</strong></div><div><span>POST-RUN CHECKS</span><strong>{check_text}</strong></div></div>{error}
<div class="section-title"><h2>Execution plan</h2><span class="mono">ORDER AS SUPPLIED</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>MIGRATION</th><th>STATE</th><th>STATEMENTS</th><th>ROW WRITES*</th></tr></thead><tbody>{steps or '<tr><td colspan="5">No migrations executed.</td></tr>'}</tbody></table></div>
{'<div class="notice"><strong>Review before applying</strong><ul>'+risks+'</ul></div>' if risks else ''}
<div class="section-title"><h2>Schema & row counts</h2><span class="mono">BEFORE / AFTER</span></div><div class="objects">{''.join(diffs) or '<p class="sub">No committed snapshot changes to display.</p>'}</div>
<div class="notes"><div><h3>What was checked</h3><p>SQLite integrity and foreign-key checks before and after the rehearsal. Failed batches roll back as one transaction. Removed tables and falling row counts require review.</p></div><div><h3>What this does not prove</h3><p>Row counts do not detect rewritten values. This is not a deployment, a production lock benchmark, or a hostile-SQL sandbox. *Row writes include trigger effects and count writes, not distinct rows.</p></div></div><footer><span>Patchday / SQLite {e(report['sqlite_version'])}</span><span>SNAPSHOT DISCARDED AFTER RUN</span></footer></main></body></html>'''
